package apply

import (
	"slices"
	"strings"
	"testing"

	"github.com/RodyMcAmp/rollgate/compiler/compile"
)

// generated returns a compiled file body under a header with the given
// source hash, as Compile writes it.
func generated(hash, body string) []byte {
	return []byte("# Generated by rollgate compile from router.toml (sha256 " + hash + ").\n" +
		"# Do not edit: change router.toml instead (docs/architecture.md#config-flow).\n" + body)
}

func planStrings(plan [][]string) []string {
	var out []string
	for _, cmd := range plan {
		out = append(out, strings.Join(cmd, " "))
	}
	return out
}

func TestReloadPlan(t *testing.T) {
	const (
		lanNet   = "etc/systemd/network/30-rollgate-lan.network"
		lanLink  = "etc/systemd/network/10-rollgate-lan.link"
		iotDev   = "etc/systemd/network/20-rollgate-iot.netdev"
		guestDev = "etc/systemd/network/20-rollgate-guest.netdev"
		ula      = "etc/rollgate/state/ula-prefix"
	)
	// Every file of the old generation, under the old config's hash.
	prev := compile.Files{
		nftablesConf: generated("aaa", "fw v1\n"),
		sysctlConf:   generated("aaa", "fwd\n"),
		dnsmasqConf:  generated("aaa", "dhcp v1\n"),
		unboundConf:  generated("aaa", "dns\n"),
		sshdConf:     generated("aaa", "ssh\n"),
		lanNet:       generated("aaa", "lan v1\n"),
		lanLink:      generated("aaa", "mac\n"),
		iotDev:       generated("aaa", "vlan 20\n"),
		guestDev:     generated("aaa", "vlan 30\n"),
		ula:          generated("aaa", "fd12::/48\n"),
	}
	// rehash returns prev under a new hash with some bodies changed, and
	// lists every path as changed, as Install would.
	rehash := func(edit map[string]string, remove ...string) (compile.Files, []string) {
		next := compile.Files{}
		for p, data := range prev {
			b := string(body(data))
			b = b[strings.Index(b, "\n")+1:] // drop the "Do not edit" line too
			if e, ok := edit[p]; ok {
				b = e
			}
			next[p] = generated("bbb", b)
		}
		for _, p := range remove {
			delete(next, p)
		}
		var changed []string
		for p := range prev {
			changed = append(changed, p)
		}
		slices.Sort(changed)
		return next, changed
	}

	t.Run("only the hash changed", func(t *testing.T) {
		next, changed := rehash(nil)
		if plan := ReloadPlan(changed, prev, next); len(plan) != 0 {
			t.Errorf("a new header alone should reload nothing, got %v", planStrings(plan))
		}
	})

	t.Run("everything, in order", func(t *testing.T) {
		next, changed := rehash(map[string]string{
			nftablesConf: "fw v2\n", sysctlConf: "nofwd\n", dnsmasqConf: "dhcp v2\n", unboundConf: "dns v2\n",
			sshdConf: "ssh v2\n", lanNet: "lan v2\n", lanLink: "mac v2\n", iotDev: "vlan 21\n", ula: "fd34::/48\n",
		}, guestDev)
		want := []string{
			"nft -f /etc/nftables.conf",
			"sysctl -p /etc/sysctl.d/90-rollgate.conf",
			"udevadm control --reload",
			"udevadm trigger --action=add --subsystem-match=net",
			"udevadm settle",
			"networkctl delete guest", // removed
			"networkctl delete iot",   // changed: networkd won't change an existing device
			"networkctl reload",
			"systemctl enable unbound.service", "systemctl restart unbound.service",
			"systemctl enable dnsmasq.service", "systemctl restart dnsmasq.service",
			"systemctl reload-or-restart sshd.service",
		}
		if got := planStrings(ReloadPlan(changed, prev, next)); !slices.Equal(got, want) {
			t.Errorf("plan:\n got %q\nwant %q", got, want)
		}
	})

	t.Run("a new VLAN is created, not deleted first", func(t *testing.T) {
		next := compile.Files{"etc/systemd/network/20-rollgate-cams.netdev": generated("bbb", "vlan 40\n")}
		got := planStrings(ReloadPlan([]string{"etc/systemd/network/20-rollgate-cams.netdev"}, compile.Files{}, next))
		if want := []string{"networkctl reload"}; !slices.Equal(got, want) {
			t.Errorf("plan %q, want %q", got, want)
		}
	})

	t.Run("revert to the distribution's defaults", func(t *testing.T) {
		base := compile.Files{
			nftablesConf: []byte("# placeholder firewall\n"),
			dnsmasqConf:  []byte("# Configuration file for dnsmasq.\n"),
			unboundConf:  []byte("server:\n"),
		}
		changed := []string{dnsmasqConf, nftablesConf, sysctlConf, unboundConf}
		want := []string{
			"nft -f /etc/nftables.conf", // sysctl file removed: nothing to load
			"systemctl disable --now unbound.service",
			"systemctl disable --now dnsmasq.service",
		}
		if got := planStrings(ReloadPlan(changed, prev, base)); !slices.Equal(got, want) {
			t.Errorf("plan:\n got %q\nwant %q", got, want)
		}
	})
}

func TestReloadStopsAtFirstFailure(t *testing.T) {
	r := &fakeRunner{fail: map[string]bool{"networkctl": true}}
	plan := [][]string{{"nft", "-f", "/etc/nftables.conf"}, {"networkctl", "reload"}, {"systemctl", "reload-or-restart", "sshd.service"}}
	err := Reload(r, plan)
	if err == nil || !strings.Contains(err.Error(), "networkctl reload: exit status 1") || !strings.Contains(err.Error(), "error on line 3") {
		t.Errorf("Reload error = %v", err)
	}
	if len(r.calls) != 2 {
		t.Errorf("ran %v; should stop after the failure", r.calls)
	}
	if err := Reload(&fakeRunner{}, plan); err != nil {
		t.Errorf("Reload with nothing failing: %v", err)
	}
}
